import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Quick correlation-based approach without clustering
    # Find features with strong association (p-value < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            # Use Welch's t-test p-value as proxy for association
            t_stat = np.abs(stats.ttest_ind(feats.x[feats.y==1,i], feats.x[feats.y==0,i], equal_var=False)[0])
            p_val = stats.t.sf(t_stat, len(feats.x[feats.y==1,i]) + len(feats.x[feats.y==0,i]) - 2) * 2
            if p_val < 0.01:
                strong_features.append((fid, i))

    # Sort by effect size (mean difference)
    strong_features.sort(key=lambda x: np.abs(np.mean(feats.x[feats.y==1,x[1]]) - np.mean(feats.x[feats.y==0,x[1]])), reverse=True)

    # Take top 10 features
    top_features = strong_features[:10]

    # Check for correlations among top features
    if len(top_features) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build correlation matrix for top features
    top_ids = [f[0] for f in top_features]
    top_cols = [f[1] for f in top_features]

    corr_matrix = np.corrcoef(feats.x[:,top_cols].T)

    # Find pairs with |r| >= 0.6
    high_corr_pairs = []
    for i in range(len(top_ids)):
        for j in range(i+1, len(top_ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                high_corr_pairs.append((top_ids[i], top_ids[j]))

    # If we have correlated pairs, form a module
    if high_corr_pairs:
        # Get all unique features involved in correlations
        module_features = set()
        for a, b in high_corr_pairs:
            module_features.add(a)
            module_features.add(b)

        # Add any remaining top features
        module_features.update(top_ids)
        module_ids = list(module_features)

        # Select first feature as driver if we have any
        driver = (module_ids[0],) if module_ids else ()

        # Weighted loading based on correlation with outcome
        loadings = {}
        for fid in module_ids:
            col_idx = feats.column(fid)
            # Use absolute correlation with outcome as loading
            corr_with_outcome = np.abs(np.corrcoef(feats.x[:,col_idx], feats.y)[0,1])
            loadings[fid] = corr_with_outcome

        # Normalize loadings
        total = sum(loadings.values())
        if total > 0:
            for fid in loadings:
                loadings[fid] /= total

        return Design(
            drivers=driver,
            columns=tuple(module_ids),
            products=(),
            loadings=loadings
        )
    else:
        # No strong correlations found
        if top_features:
            # Return first feature as driver
            return Design(
                drivers=(top_features[0][0],),
                columns=(top_features[0][0],),
                products=(),
                loadings={top_features[0][0]: 1.0}
            )
        else:
            return Design(drivers=(), columns=(), products=(), loadings={})

